CREATE TABLE IF NOT EXISTS app_user(id uuid PRIMARY KEY,username text NOT NULL UNIQUE,display_name text NOT NULL,password_hash text NOT NULL,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','disabled')),failed_attempts int NOT NULL DEFAULT 0,locked_until timestamptz,permission_version bigint NOT NULL DEFAULT 1,password_changed_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS role(id text PRIMARY KEY,name text NOT NULL,description text NOT NULL,builtin boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS permission(id text PRIMARY KEY,module text NOT NULL,action text NOT NULL,description text NOT NULL);
CREATE TABLE IF NOT EXISTS role_permission(role_id text NOT NULL REFERENCES role(id),permission_id text NOT NULL REFERENCES permission(id),PRIMARY KEY(role_id,permission_id));
CREATE TABLE IF NOT EXISTS project(id text PRIMARY KEY,name text NOT NULL,code text NOT NULL,status text NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS user_global_role(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES app_user(id),role_id text NOT NULL REFERENCES role(id),valid_from timestamptz NOT NULL DEFAULT now(),expires_at timestamptz,revoked_at timestamptz,created_by uuid REFERENCES app_user(id));
CREATE UNIQUE INDEX IF NOT EXISTS active_global_role ON user_global_role(user_id,role_id) WHERE revoked_at IS NULL;
CREATE TABLE IF NOT EXISTS project_membership(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES app_user(id),project_id text NOT NULL REFERENCES project(id),role_id text NOT NULL REFERENCES role(id),resource_type text NOT NULL DEFAULT '',resource_id text NOT NULL DEFAULT '',valid_from timestamptz NOT NULL DEFAULT now(),expires_at timestamptz,revoked_at timestamptz,created_by uuid REFERENCES app_user(id));
CREATE UNIQUE INDEX IF NOT EXISTS active_project_role ON project_membership(user_id,project_id,role_id,resource_type,resource_id) WHERE revoked_at IS NULL;
ALTER TABLE api_session ADD COLUMN IF NOT EXISTS user_id uuid REFERENCES app_user(id);
ALTER TABLE api_session ADD COLUMN IF NOT EXISTS revoked_at timestamptz;
ALTER TABLE api_session ADD COLUMN IF NOT EXISTS last_seen_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE api_session ADD COLUMN IF NOT EXISTS user_agent text NOT NULL DEFAULT '';
ALTER TABLE api_session ADD COLUMN IF NOT EXISTS ip text NOT NULL DEFAULT '';
UPDATE api_session SET revoked_at=now() WHERE user_id IS NULL AND revoked_at IS NULL;
CREATE TABLE IF NOT EXISTS login_event(id uuid PRIMARY KEY,user_id uuid REFERENCES app_user(id),username text NOT NULL,outcome text NOT NULL,ip text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS login_rate_window ON login_event(ip,created_at);
CREATE TABLE IF NOT EXISTS approval_record(id uuid PRIMARY KEY,project_id text NOT NULL REFERENCES project(id),requester_id uuid NOT NULL REFERENCES app_user(id),action text NOT NULL,resource_type text NOT NULL,resource_id text NOT NULL,snapshot_version text NOT NULL,risk text NOT NULL,state text NOT NULL DEFAULT 'pending',required_groups jsonb NOT NULL,targets jsonb NOT NULL DEFAULT '[]',reason text NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS approval_signature(approval_id uuid NOT NULL REFERENCES approval_record(id),user_id uuid NOT NULL REFERENCES app_user(id),group_id text NOT NULL,decision text NOT NULL,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(approval_id,user_id),UNIQUE(approval_id,group_id));
INSERT INTO project(id,name,code) VALUES('proj-b300-demo','B300 64节点交付项目','B300-DEMO-64'),('proj-a100-demo','扩展项目（无演示设备）','PROJECT-02'),('proj-lab-demo','实验项目（无演示设备）','PROJECT-03') ON CONFLICT(id) DO NOTHING;
INSERT INTO project(id,name,code) SELECT DISTINCT project_id,project_id,project_id FROM bom_import_batch ON CONFLICT(id) DO NOTHING;
